(function(root){const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const color=c=>/^#[0-9a-f]{3,8}$|^(transparent|white|black)$/i.test(c||'')?c:'transparent';function page(d,s){return d.pages.find(p=>p.id===s.page)||d.pages.find(p=>p.id===d.startPage)||d.pages[0]}function activate(d,s,id){const e=page(d,s).elements.find(e=>e.id===id);if(!e?.targetPage)return false;if(e.targetPage==='back')s.page=s.stack.pop()||d.startPage;else{if(!d.pages.some(p=>p.id===e.targetPage))throw Error('目标页面已不存在，请重新配置');s.stack.push(page(d,s).id);s.page=e.targetPage}return true}function render(d,s){const p=page(d,s);return `<div class="sv-viewport" style="margin:20px auto"><div class="prototype-scroll" style="width:600px;height:800px;zoom:.5;overflow:auto;background:#111111"><div style="position:relative;height:${Math.max(800,Math.min(8000,+p.scrollHeight||800))}px">${p.elements.map(e=>`<div data-proto="${esc(e.id)}" tabindex="${e.targetPage?0:-1}" role="${e.targetPage?'button':'group'}" style="position:absolute;box-sizing:border-box;white-space:pre-wrap;overflow:hidden;left:${+e.x||0}px;top:${+e.y||0}px;width:${+e.w||100}px;height:${+e.h||100}px;font-size:${+e.fontSize||32}px;color:${color(e.color)};background:${color(e.background)};border-radius:${+e.radius||0}px;padding:${e.type==='card'?24:0}px;cursor:${e.targetPage?'pointer':'default'}">${root.GlassGraphics?root.GlassGraphics.element(e):esc(e.text)}</div>`).join('')}</div></div></div>`}root.PrototypeRuntime={page,activate,render}})(globalThis);
